    private static String witnessRecord(Txn txn) throws Exception {
        List<String> operations = new ArrayList<>();
        txn.additions().stream().map(Rdf4jCrashlabOracle::canonicalStatement)
                .map(statement -> "+" + statement).forEach(operations::add);
        txn.removals().stream().map(Rdf4jCrashlabOracle::canonicalStatement)
                .map(statement -> "-" + statement).forEach(operations::add);
        if (txn.namespace() != null) {
            operations.add("namespace:crash=" + txn.namespace());
        }
        operations.sort(Comparator.naturalOrder());
        return txn.id() + "\t" + sha256(String.join("\n", operations)) + "\t"
                + txn.additions().size() + "\t" + txn.removals().size();
    }

