    private static Set<Statement> filter(Set<Statement> statements,
            java.util.function.Predicate<Statement> predicate) {
        return statements.stream().filter(predicate).collect(java.util.stream.Collectors.toCollection(LinkedHashSet::new));
    }

    private static Set<Statement> queryStatements(RepositoryConnection connection, Resource subject, IRI predicate,
            Value object, Resource... contexts) {
        Set<Statement> statements = new LinkedHashSet<>();
        try (RepositoryResult<Statement> result = connection.getStatements(subject, predicate, object, false, contexts)) {
            while (result.hasNext()) {
                Statement statement = result.next();
                if (!statements.add(statement)) {
                    throw new AssertionError("index lookup returned a duplicate: " + statement);
                }
            }
        }
        return statements;
    }

    private static String canonicalStatement(Statement statement) {
        return canonicalValue(statement.getSubject()) + " " + canonicalValue(statement.getPredicate()) + " "
                + canonicalValue(statement.getObject()) + " "
                + (statement.getContext() == null ? "DEFAULT" : canonicalValue(statement.getContext()));
    }

    private static String canonicalValue(Value value) {
        if (value instanceof IRI iri) {
            return "<" + iri.stringValue() + ">";
        }
        if (value instanceof BNode bNode) {
            return "_:" + bNode.getID();
        }
        if (value instanceof Literal literal) {
            String language = literal.getLanguage().orElse("");
            return "\"" + literal.getLabel().replace("\\", "\\\\").replace("\"", "\\\"") + "\"@"
                    + language + "^^<" + literal.getDatatype().stringValue() + ">";
        }
        if (value instanceof TripleTerm triple) {
            return "<<" + canonicalValue(triple.getSubject()) + " " + canonicalValue(triple.getPredicate()) + " "
                    + canonicalValue(triple.getObject()) + ">>";
        }
        throw new IllegalArgumentException("Unsupported RDF value: " + value.getClass().getName());
    }

    private static String sha256(String value) throws Exception {
        byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
        StringBuilder result = new StringBuilder(digest.length * 2);
        for (byte b : digest) {
            result.append(Character.forDigit((b >>> 4) & 0xf, 16));
            result.append(Character.forDigit(b & 0xf, 16));
        }
        return result.toString();
    }

    private static void assertEquals(Object expected, Object actual, String label) {
        if (!Objects.equals(expected, actual)) {
            throw new AssertionError(label + " mismatch: expected=" + expected + " actual=" + actual);
        }
    }

    private static void forceWrite(Path path, String value) throws IOException {
        byte[] bytes = value.getBytes(StandardCharsets.UTF_8);
        try (FileChannel channel = FileChannel.open(path, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE)) {
            ByteBuffer buffer = ByteBuffer.wrap(bytes);
            while (buffer.hasRemaining()) {
                channel.write(buffer);
            }
            channel.force(true);
        }
    }

